select private.rc_release_guide(
  p_slug => 'bookings-new-request',
  p_tool_key => 'bookings',
  p_title => 'Entering a request and its estimate',
  p_summary => 'One form creates the request, prices it and plans its dates; what the summary line says, what to do when a date does not work, and the warning badges.',
  p_screen_keys => array['bookings.requests', 'bookings.project'],
  p_sort_order => 19,
  p_version_note => 'Refinement pass, slice A: the happy path',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A new request is also its estimate. Open "},{"type":"text","text":"Requests","marks":[{"type":"bold"}]},{"type":"text","text":" and choose "},{"type":"text","text":"+ New request","marks":[{"type":"bold"}]},{"type":"text","text":", pick who it is for, tick the service they need and give the event date. One click on "},{"type":"text","text":"Create and price the estimate","marks":[{"type":"bold"}]},{"type":"text","text":" starts the request, prices it and plans the dates."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What you see"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One line at the top of the request says what it is, how much work it takes, what the partner pays, whether the calendar has room, what WUWF contributes and when the estimate expires."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The rate is named in plain words: "},{"type":"text","text":"University rate","marks":[{"type":"bold"}]},{"type":"text","text":" (the partner pays the full cost), "},{"type":"text","text":"University rate (WUWF contributing)","marks":[{"type":"bold"}]},{"type":"text","text":" (the partner pays for students and equipment and WUWF contributes the staff time) or "},{"type":"text","text":"Outside rate","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Show calculation","marks":[{"type":"bold"}]},{"type":"text","text":" opens the estimate lines, how the rate was worked out and the version of the rates it came from. Most requests never need it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The dates"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The service books itself: the date you give is checked against the calendar and the dates are planned automatically. Tentative holds are placed when you send the estimate, as before."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the date can't work — the studio is booked, WUWF has something on, the day is full — the request shows "},{"type":"text","text":"The dates need attention","marks":[{"type":"bold"}]},{"type":"text","text":" with the reason and the nearest dates that do work. Choose one to move the event."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adjust scope","marks":[{"type":"bold"}]},{"type":"text","text":" is the way to plan dates by hand. Once you add or remove a date yourself the system stops changing them."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Strategic work"}]},{"type":"paragraph","content":[{"type":"text","text":"For a UWF unit the form asks one question: is this strategic or applied-learning work? If yes, and WUWF has time set aside for it, WUWF contributes the staff time. If the time has run out the request is priced at the university rate and flagged, and it stays recorded as strategic work. You can leave it unanswered and answer from the request later."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Warning badges"}]},{"type":"paragraph","content":[{"type":"text","text":"A request that is out of the ordinary carries a warning badge in the list and on its page — a rate set by hand, a booking exception, contribution time used up, or dates that need attention. An ordinary request carries none."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-07-bookings-happy-path',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-07',
  p_title => 'Bookings: a request is also its estimate',
  p_guide_slugs => array['bookings-new-request'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Entering a request now prices it at the same time. Choose the partner, tick the service and give the event date; the estimate is priced, the dates are checked against the calendar and planned, and one line at the top of the request says what it comes to and what WUWF contributes. If the date can't work, the request names the reason and offers the nearest dates that do. The rate names are now plain — University rate, University rate (WUWF contributing) and Outside rate — and the detail of the calculation is one click away under Show calculation. Production staff see the Rates tab under the ⋯ menu; it hasn't gone anywhere."}]}]}$body$
);
